SELECT DB_NAME() COLLATE Latin1_General_100_BIN2 AS DatabaseName,N'PRINCIPAL' COLLATE Latin1_General_100_BIN2 AS Kind,p.name COLLATE Latin1_General_100_BIN2 AS Name,ISNULL(USER_NAME(p.owning_principal_id),N'') COLLATE Latin1_General_100_BIN2 AS Related,CONVERT(nvarchar(128),p.type) COLLATE Latin1_General_100_BIN2 AS Type,ISNULL((SELECT name FROM sys.server_principals WHERE sid=p.sid),N'') COLLATE Latin1_General_100_BIN2 AS Value,CONCAT(p.authentication_type,N':',p.is_fixed_role) COLLATE Latin1_General_100_BIN2 AS Flags
FROM sys.database_principals p
UNION ALL SELECT DB_NAME(),N'MEMBER',USER_NAME(role_principal_id),USER_NAME(member_principal_id),N'',N'',N'' FROM sys.database_role_members
UNION ALL SELECT DB_NAME(),N'SIGNATURE',CONVERT(nvarchar(128),p.major_id),CONVERT(nvarchar(128),p.class),CONVERT(nvarchar(128),p.crypt_type),COALESCE(c.name,k.name,N'<UNRESOLVED>'),N'' FROM sys.crypt_properties p LEFT JOIN sys.certificates c ON c.thumbprint=p.thumbprint LEFT JOIN sys.asymmetric_keys k ON k.thumbprint=p.thumbprint
UNION ALL SELECT DB_NAME(),N'TRIGGER',CONVERT(nvarchar(128),object_id),CONVERT(nvarchar(128),parent_id),CONVERT(nvarchar(128),parent_class),CONVERT(nvarchar(128),is_disabled),CONVERT(nvarchar(128),is_instead_of_trigger) FROM sys.triggers
UNION ALL SELECT DB_NAME(),N'TRIGGER_EVENT',CONVERT(nvarchar(128),object_id),CONVERT(nvarchar(128),type),N'',CONVERT(nvarchar(128),is_first),CONVERT(nvarchar(128),is_last) FROM sys.trigger_events
UNION ALL SELECT DB_NAME(),N'POLICY',CONVERT(nvarchar(128),object_id),N'',N'',CONVERT(nvarchar(128),is_enabled),CONVERT(nvarchar(128),is_schema_bound) FROM sys.security_policies
UNION ALL SELECT DB_NAME(),N'PREDICATE',CONVERT(nvarchar(128),object_id),CONVERT(nvarchar(128),target_object_id),CONVERT(nvarchar(128),predicate_type),predicate_definition,CONVERT(nvarchar(128),operation) FROM sys.security_predicates
UNION ALL SELECT DB_NAME(),N'SERVER_PRINCIPAL',p.name,ISNULL(SUSER_NAME(p.owning_principal_id),N''),CONVERT(nvarchar(128),p.type),N'',CONVERT(nvarchar(128),p.is_disabled) FROM sys.server_principals p WHERE DB_NAME()='master' AND p.name<>'AiCimdCatalogSignerV2' AND (p.type IN('C','K') OR p.name LIKE '##MS[_]%' OR p.name='public' OR p.sid=0x01)
UNION ALL SELECT DB_NAME(),N'SERVER_PERMISSION',s.name,ISNULL(SUSER_NAME(p.grantor_principal_id),N''),CONCAT(p.class,N':',p.major_id),p.permission_name,CONVERT(nvarchar(128),p.state) FROM sys.server_permissions p JOIN sys.server_principals s ON s.principal_id=p.grantee_principal_id WHERE DB_NAME()='master' AND s.name<>'AiCimdCatalogSignerV2' AND (s.type IN('C','K') OR s.name LIKE '##MS[_]%' OR s.name='public' OR s.sid=0x01)
UNION ALL SELECT DB_NAME(),N'SERVER_MEMBER',SUSER_NAME(r.role_principal_id),s.name,N'',N'',N'' FROM sys.server_role_members r JOIN sys.server_principals s ON s.principal_id=r.member_principal_id WHERE DB_NAME()='master' AND s.name<>'AiCimdCatalogSignerV2' AND (s.type IN('C','K') OR s.name LIKE '##MS[_]%' OR s.name='public' OR s.sid=0x01)
UNION ALL SELECT DB_NAME(),N'SERVER_OWNED',p.name,o.name,CONVERT(nvarchar(128),p.type),N'',N'' FROM sys.server_principals p JOIN sys.server_principals o ON o.principal_id=p.owning_principal_id WHERE DB_NAME()='master' AND o.name<>'AiCimdCatalogSignerV2' AND (o.type IN('C','K') OR o.name LIKE '##MS[_]%' OR o.name='public')
